def module(records):
    """
    Add boolean field 'outlier' to every record in records.
    A record is marked True when its 'value' deviates from the batch median
    by more than three times the batch median absolute deviation (MAD).
    If the batch MAD is zero (degenerate spread) then no record is marked an outlier.
    Other fields in each record are left unchanged. The function returns the same
    list of records (mutated in place).
    """
    # Helper to compute median of a sequence of numbers
    def _median(seq):
        n = len(seq)
        if n == 0:
            return None
        s = sorted(seq)
        mid = n // 2
        if n % 2 == 1:
            return float(s[mid])
        else:
            return (s[mid - 1] + s[mid]) / 2.0

    if not records:
        return records

    # Extract numeric values (as floats) in input order
    try:
        values = [float(r['value']) for r in records]
    except KeyError:
        raise KeyError("All records must have a 'value' field.")
    except (TypeError, ValueError):
        raise ValueError("All 'value' fields must be numeric.")

    med = _median(values)
    # If med is None (no records) treat as no outliers
    if med is None:
        for rec in records:
            rec['outlier'] = False
        return records

    deviations = [abs(v - med) for v in values]
    mad = _median(deviations)

    # Degenerate spread: no outliers
    if mad == 0 or mad is None:
        for rec in records:
            rec['outlier'] = False
        return records

    threshold = 3.0 * mad
    for rec, v in zip(records, values):
        rec['outlier'] = abs(v - med) > threshold

    return records

