    Add a boolean field 'outlier' to every record in `records`.
    A record is an outlier when abs(value - median) > 3 * MAD,
    where MAD is the median of absolute deviations from the median.
    If the batch spread is degenerate (MAD == 0) or median cannot be computed,
    no records are marked as outliers.
    The function mutates the input records and also returns them.
    """
    import statistics

    # If no records, nothing to do.
    if not records:
        return records

    # Extract values in the same order as records.
    try:
        values = [rec['value'] for rec in records]
    except Exception:
        # If any record lacks 'value' key, treat batch as degenerate: no outliers.
        for rec in records:
            rec['outlier'] = False
        return records

    # Try to compute median; if fails (e.g., non-numeric), treat as degenerate.
    try:
        med = statistics.median(values)
    except Exception:
        for rec in records:
            rec['outlier'] = False
        return records

    # Compute absolute deviations and MAD.
    try:
        deviations = [abs(v - med) for v in values]
        mad = statistics.median(deviations)
    except Exception:
        for rec in records:
            rec['outlier'] = False
        return records

    # Degenerate spread -> no outliers
    if mad == 0:
        for rec in records:
            rec['outlier'] = False
        return records

    threshold = 3 * mad
    # Mark outliers
    for rec, v in zip(records, values):
        try:
            rec['outlier'] = abs(v - med) > threshold
        except Exception:
            # If any per-record computation fails, mark it non-outlier
            rec['outlier'] = False

    return records

