def module(records):
    from fractions import Fraction
    from decimal import Decimal

    budget = 1000

    # Empty input -> empty output
    if not records:
        return []

    # Helper to convert weight to exact Fraction when possible
    def _to_frac(w):
        # Treat missing or non-numeric as zero
        try:
            # Use Decimal(str(w)) to get a decimal representation for floats/ints/Decimals
            return Fraction(Decimal(str(w)))
        except Exception:
            try:
                return Fraction(w)
            except Exception:
                return Fraction(0)

    n = len(records)
    weights = [_to_frac(r.get('weight', 0)) for r in records]

    # Identify positive weights and total
    positive_flags = [w > 0 for w in weights]
    total_weight = sum(w for w, f in zip(weights, positive_flags) if f)

    # Prepare initial allocations and fractional parts
    allocs = [0] * n
    fracs = [Fraction(0)] * n

    if total_weight > 0:
        for i, (w, is_pos) in enumerate(zip(weights, positive_flags)):
            if is_pos:
                exact = Fraction(budget) * w / total_weight
                floor_share = int(exact)  # exact >= 0 so int() is floor
                allocs[i] = floor_share
                fracs[i] = exact - floor_share
            else:
                allocs[i] = 0
                fracs[i] = Fraction(0)
    else:
        # No positive weights: all initial allocs 0, fracs 0
        allocs = [0] * n
        fracs = [Fraction(0)] * n

    used = sum(allocs)
    remaining = budget - used

    if remaining > 0:
        # Sort indices by fractional part (descending), ties by earlier index
        indices = list(range(n))
        indices.sort(key=lambda i: (-fracs[i], i))
        # Give +1 to the top 'remaining' indices
        for i in range(remaining):
            allocs[indices[i]] += 1

    # Write alloc (as int) into each record and return records
    for r, a in zip(records, allocs):
        r['alloc'] = int(a)

    return records

