def module(records):
    from fractions import Fraction

    if not records:
        return []

    # Helper to coerce a weight to a Fraction; non-numeric becomes 0
    def to_fraction(v):
        if isinstance(v, Fraction):
            return v
        if isinstance(v, int):
            return Fraction(v, 1)
        if isinstance(v, float):
            # exact rational representation of the binary float
            return Fraction.from_float(v)
        try:
            return Fraction(v)
        except Exception:
            try:
                return Fraction.from_float(float(v))
            except Exception:
                return Fraction(0, 1)

    # Collect positive weights and compute total
    weights = []
    for r in records:
        w = r.get('weight', 0)
        fw = to_fraction(w)
        # treat strictly positive fractional values as positive weights
        if fw > 0:
            weights.append(fw)
        else:
            weights.append(Fraction(0, 1))

    total_positive = sum(w for w in weights if w > 0)

    n = len(records)
    shares = [Fraction(0, 1)] * n

    if total_positive > 0:
        # distribute proportionally among records with positive weights; others get 0
        for i, w in enumerate(weights):
            if w > 0:
                shares[i] = w * Fraction(1000, 1) / total_positive
            else:
                shares[i] = Fraction(0, 1)
    else:
        # no positive weights: distribute equally among all records
        equal_share = Fraction(1000, 1) / n
        for i in range(n):
            shares[i] = equal_share

    # Floor the shares and compute fractional parts
    floors = [int(s) for s in shares]  # s is non-negative Fraction; int() gives floor
    frac_parts = [shares[i] - floors[i] for i in range(n)]

    floors_sum = sum(floors)
    remainder = 1000 - floors_sum

    # If, for some unforeseen reason, floors_sum > 1000, reduce allocations from smallest fractional parts
    if remainder < 0:
        # need to remove (-remainder) units
        to_remove = -remainder
        # sort by fractional part ascending, tie by later index removed first? Spec doesn't cover this case;
        # choose to remove from smallest fractional parts, breaking ties by latest record to favor earlier ones
        order = sorted(range(n), key=lambda i: (frac_parts[i], -i))
        idx = 0
        while to_remove > 0 and idx < n:
            i = order[idx]
            # only remove if there's at least 1 to remove
            if floors[i] > 0:
                floors[i] -= 1
                to_remove -= 1
            idx += 1
        remainder = 1000 - sum(floors)

    # Distribute the remaining units to records with largest fractional parts, earliest record wins ties.
    if remainder > 0:
        order = sorted(range(n), key=lambda i: (-frac_parts[i], i))
        for j in range(remainder):
            floors[order[j]] += 1

    # Write allocs (integers) onto records, leaving other fields unchanged
    for i, r in enumerate(records):
        r['alloc'] = int(floors[i])

    return records

