def module(records):
    """
    Adds a boolean 'outlier' field to each record in `records`.
    A record is an outlier if |value - median| > 3 * MAD, where MAD is the
    median absolute deviation of the batch. If the batch has degenerate spread
    (MAD == 0) no records are marked as outliers. Other fields are left untouched.
    The function mutates the input records in place and returns the list.
    """
    # If no records, nothing to do
    if not records:
        return records

    # Extract values in original order
    try:
        values = [r['value'] for r in records]
    except Exception:
        # If values cannot be extracted, do not mark any outliers
        for r in records:
            r['outlier'] = False
        return records

    # Helper to compute median of a non-empty list of numbers
    def median(seq):
        n = len(seq)
        if n == 0:
            return 0
        s = sorted(seq)
        mid = n // 2
        if n % 2 == 1:
            return s[mid]
        else:
            return (s[mid - 1] + s[mid]) / 2.0

    med = median(values)
    deviations = [abs(v - med) for v in values]
    mad = median(deviations)

    # Degenerate spread: no outliers
    if mad == 0:
        for r in records:
            r['outlier'] = False
        return records

    threshold = 3 * mad
    for r in records:
        try:
            r['outlier'] = abs(r['value'] - med) > threshold
        except Exception:
            # If a value is not comparable, do not mark it as outlier
            r['outlier'] = False

    return records
